function validate(input) {
  const [{ employees = [], meetings = [] }] = input;
  const staff = new Set(), names = new Set(), ids = new Set();
  for (const [id, name, department] of employees) {
    if ([id, name, department].includes(null)) return 'No value in employees may be null.';
    if (staff.has(id)) return `employee_id ${id} appears twice in employees.`;
    staff.add(id);
    const folded = String(name).toLowerCase();
    if (names.has(folded)) return `Two employees are named ${name}.`;
    names.add(folded);
  }
  for (const [id, employee, day, type, hours] of meetings) {
    if ([id, employee, day, type, hours].includes(null)) return 'No value in meetings may be null.';
    if (ids.has(id)) return `meeting_id ${id} appears twice in meetings.`;
    ids.add(id);
    if (!staff.has(employee)) return `employee_id ${employee} is not in employees.`;
    if (!/^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(day)) return `meeting_date ${day} must look like 2023-06-05.`;
    if (!['Team', 'Client', 'Training'].includes(type)) return `meeting_type ${type} must be Team, Client or Training.`;
    if (!(hours > 0 && hours <= 99.99)) return 'duration_hours must be above 0 and at most 99.99.';
  }
  return null;
}

