function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const firsts = ['Alice', 'Bob', 'Carol', 'David', 'Emma', 'Frank', 'Grace', 'Henry', 'Ivy', 'Jack', 'Kara', 'Liam', 'Mia', 'Noah', 'Olga', 'Paul', 'Quinn', 'Rosa', 'Sam', 'Tina'];
  const lasts = ['Johnson', 'Smith', 'Davis', 'Wilson', 'Brown', 'Lee', 'Kim', 'Patel', 'Garcia', 'Novak'];
  const departments = ['Engineering', 'Marketing', 'Sales', 'HR'];
  // Unique names: shuffle every first-last pair and take them in order.
  const pool = [];
  for (const f of firsts) for (const l of lasts) pool.push(`${f} ${l}`);
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const people = small ? (rand() < 0.1 ? 0 : 1 + Math.floor(rand() * 3)) : 150;
  const employees = [];
  for (let i = 0; i < people; i++) employees.push([small ? i + 1 : 100 + i, pool[i], pick(departments)]);
  // Days run over a few weeks around a new year so weeks cross the year boundary.
  const start = Date.UTC(2024, 11, small ? 21 : 16), span = small ? 16 : 49;
  const day = () => new Date(start + Math.floor(rand() * span) * 86400000).toISOString().slice(0, 10);
  // Quarter-hour amounts add up exactly, and pairs often land on exactly 20 hours.
  const hours = small ? [6.5, 8, 10, 12, 13.5, 20, 21, 25] : [1.5, 2, 3.25, 4, 5, 6.5, 7.75, 8, 10, 12];
  const count = employees.length === 0 ? 0 : small ? Math.floor(rand() * 9) : 2000;
  const meetings = [];
  for (let i = 0; i < count; i++) meetings.push([i + 1, pick(employees)[0], day(), pick(['Team', 'Client', 'Training']), pick(hours)]);
  return [{ employees, meetings }];
}
